package com.justclick.clicknbook.Fragment.qrupicashimport android.app.AlertDialogimport android.app.Dialogimport android.content.Contextimport android.graphics.Bitmapimport android.os.Bundleimport android.view.*import android.widget.ImageViewimport android.widget.TextViewimport android.widget.Toast//import androidmads.library.qrgenearator.QRGContents//import androidmads.library.qrgenearator.QRGEncoderimport androidx.fragment.app.Fragmentimport com.bumptech.glide.Glideimport com.google.gson.Gsonimport com.google.zxing.BarcodeFormatimport com.journeyapps.barcodescanner.BarcodeEncoder//import com.google.zxing.WriterExceptionimport com.justclick.clicknbook.ApiConstantsimport com.justclick.clicknbook.Rimport com.justclick.clicknbook.databinding.FragmentQrUpiCashBindingimport com.justclick.clicknbook.model.LoginModelimport com.justclick.clicknbook.myinterface.ToolBarHideFromFragmentListenerimport com.justclick.clicknbook.network.NetworkCallimport com.justclick.clicknbook.utils.Commonimport com.justclick.clicknbook.utils.MyPreferencesimport okhttp3.ResponseBodyimport java.net.URLimport java.util.Scannerclass QRUpiCashFragment : Fragment() {    var toolBarHideFromFragmentListener: ToolBarHideFromFragmentListener?=null    var loginModel:LoginModel?=null    var userData:String?=null    var token:String?=null    var isCredential=false    var binding:FragmentQrUpiCashBinding?=null    companion object {        @JvmStatic        fun newInstance() =            QRUpiCashFragment().apply {                arguments = Bundle().apply {                }            }    }    override fun onAttach(context: Context) {        super.onAttach(context)        toolBarHideFromFragmentListener=context as ToolBarHideFromFragmentListener        loginModel= LoginModel()        loginModel=MyPreferences.getLoginData(loginModel,context)    }    override fun onCreate(savedInstanceState: Bundle?) {        super.onCreate(savedInstanceState)    }    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View? {        // Inflate the layout for this fragment        binding=FragmentQrUpiCashBinding.inflate(layoutInflater)        toolBarHideFromFragmentListener!!.onToolBarHideFromFragment(true)        binding!!.backArrow.setOnClickListener{            parentFragmentManager.popBackStack()        }        binding!!.cancelTv.setOnClickListener{            parentFragmentManager.popBackStack()        }        binding!!.selfTv.setOnClickListener{            binding!!.mobileEdt.setText(MyPreferences.getLoginData(LoginModel(),requireContext()).Data.Mobile)        }        binding!!.qrTv!!.setOnClickListener{            if(isCredential){                getCredentials()            }else{                payClicked()            }        }        getCredentials()        getIpAddress()        return binding!!.root    }    private fun payClicked() {        var mobile=binding!!.mobileEdt.text.toString().trim()        var amount=binding!!.amountEdt.text.toString().trim()        if(mobile.isEmpty()){            Toast.makeText(context,"Please enter mobile number", Toast.LENGTH_SHORT).show()            return        }else if(!Common.isMobileValid(mobile)){            Toast.makeText(context, R.string.empty_and_invalid_mobile, Toast.LENGTH_SHORT).show()            return        }else if(!Common.isdecimalvalid(amount)){            Toast.makeText(context, R.string.empty_and_invalid_amount, Toast.LENGTH_SHORT).show()            return        }else if(amount.toInt()<100 || amount.toInt()>50000){            Toast.makeText(context, "Amount should be in between 100 to 50000", Toast.LENGTH_SHORT).show()            return        }//        Toast.makeText(context, "Submit clicked", Toast.LENGTH_SHORT).show()        getQr(mobile, amount)    }    class CredentialRequest{        var MerchantId=ApiConstants.MerchantId        var AgentCode:String?=null        var Mode="App"    }    private fun getCredentials() {        var request= CredentialRequest()        request.AgentCode=loginModel!!.Data.DoneCardUser        NetworkCall().callService(NetworkCall.getCashFreeQRApiInterface().getQRAuth(ApiConstants.Authentication, request), requireContext(), true        ) { response: ResponseBody?, responseCode: Int ->            if (response != null) {                responseHandlerCredential(response, 1) //https://remittance.justclicknpay.com/api/payments/CheckCredential            } else {      //{"AgentCode":"JC0A13387","MerchantId":"JUSTCLICKTRAVELS","Mode":"App"}                Toast.makeText(requireContext(), R.string.response_failure_message, Toast.LENGTH_SHORT).show()            }        }    }    class CredentialResponse{        var statusCode:String?=null        var statusMessage:String?=null        var authvalidation:ArrayList<Authvalidation>?=null        class Authvalidation{            var token:String?=null            var userData:String?=null        }        /*"statusCode": "00",    "statusMessage": "Credential validated Successfully.",    "authvalidation"*/    }    private fun responseHandlerCredential(response: ResponseBody, i: Int) {        try {            val senderResponse = Gson().fromJson(response.string(), CredentialResponse::class.java)            if (senderResponse != null) {                if (senderResponse.statusCode == "00") {//                    Toast.makeText(context, senderResponse.statusMessage, Toast.LENGTH_LONG).show()//                    vpaCheck(senderResponse)                    userData=senderResponse.authvalidation!!.get(0).userData                    token=senderResponse.authvalidation!!.get(0).token                    if(isCredential){                        isCredential=false                    }                } else {                    Toast.makeText(context, senderResponse.statusMessage, Toast.LENGTH_LONG).show()                    isCredential=true                }            } else {//                hideCustomDialog()//                Toast.makeText(context, "Validation failed", Toast.LENGTH_SHORT).show()                alertDialog("Validation failed")            }        } catch (e: Exception) {//            hideCustomDialog()            alertDialog("Validation failed with exception")        }    }    private fun getQr(mobile: String, amount: String) {        var request= UpiCashRequest()        request.AgentCode=loginModel!!.Data.DoneCardUser        request.Mobile=mobile        request.Amount=Integer.parseInt(amount)        request.Latitude="27.18768"        request.Longitude="77.85781"        request.Ip=ip        val json = Gson().toJson(request)        NetworkCall().callService(NetworkCall.getAepsInterface().getQrUpiCash(ApiConstants.upiwithdrawal,            request, userData, "Bearer "+token), context, true        ) { response: ResponseBody?, responseCode: Int ->            if (response != null) {                responseHandlerQR(response) //https://remittance.justclicknpay.com/api/payments/CheckCredential            } else {      //{"AgentCode":"JC0A13387","MerchantId":"JUSTCLICKTRAVELS","Mode":"App"}                Toast.makeText(requireContext(), R.string.response_failure_message, Toast.LENGTH_SHORT).show()            }        }    }    private fun responseHandlerQR(response: ResponseBody) {        try {            val senderResponse = Gson().fromJson(response.string(), QrUpiCashResponse::class.java)            if (senderResponse != null) {                if (senderResponse.statusCode == "00") {//                    Toast.makeText(requireContext(), senderResponse.statusMessage, Toast.LENGTH_LONG).show()                    generateQr2(senderResponse.data!!.qrMobile, senderResponse.data!!.transactionValue)//                    activeQrConfirm(credentialRequest)                } else {//                    Toast.makeText(requireContext(), senderResponse.statusMessage, Toast.LENGTH_LONG).show()                    alertDialog(senderResponse.statusMessage)//                    hideCustomDialog()                }            } else {//                hideCustomDialog()//                Toast.makeText(requireContext(), "Validation failed", Toast.LENGTH_SHORT).show()                alertDialog("Response error")            }        } catch (e: Exception) {//            hideCustomDialog()            alertDialog("Response error with exception")        }    }    private fun alertDialog(message: String?) {        val builder = AlertDialog.Builder(requireContext())        //set title for alert dialog        builder.setTitle("Alert")        //set message for alert dialog        builder.setMessage(message)//        builder.setIcon(android.R.drawable.ic_dialog_alert)        // Create the AlertDialog        var alertDialog: AlertDialog?=null        builder.setPositiveButton("OK"){dialogInterface, which ->            alertDialog!!.dismiss()//            parentFragmentManager.popBackStack()        }        alertDialog= builder.create()        // Set other dialog properties        alertDialog.setCancelable(false)        alertDialog.show()    }    private fun generateQr2(qrCode: String?, transactionValue: String?) {        val dialog = Dialog(requireContext())        dialog.setContentView(R.layout.qr_upi_cash_dialog_view)        //        dialog.getWindow().setLayout(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);        dialog.setCancelable(false)        //        dialog.getWindow().getAttributes().windowAnimations = R.style.animation;        val messageTv = dialog.findViewById<TextView>(R.id.messageTv)        val okTv = dialog.findViewById<TextView>(R.id.okTv)        val qrImg = dialog.findViewById<ImageView>(R.id.qrImg)        messageTv.text = "Payable amount: "+resources.getString(R.string.rupeeSymbolRs)+" "+transactionValue//        Glide.with(context)//            .load(qrCode)//            .into(qrImg)        val barcodeEncoder = BarcodeEncoder()        // Encode the string URL into a 500x500 Matrix Bitmap        val bitmap: Bitmap = barcodeEncoder.encodeBitmap(            qrCode,            BarcodeFormat.QR_CODE,            600,            600        )        qrImg.setImageBitmap(bitmap)        okTv.setOnClickListener { dialog.dismiss() }        dialog.show()    }    var ip: String? = null    fun getIpAddress() {        requireActivity().runOnUiThread {            try {                val url = URL("https://api.ipify.org")                val connection = url.openConnection()                connection.setRequestProperty(                    "User-Agent",                    "Mozilla/5.0/Chrome"                ) // Set a User-Agent to avoid HTTP 403 Forbidden error                val inputStream = connection.getInputStream()                val s = Scanner(inputStream, "UTF-8").useDelimiter("\\A")                ip = s.next()                inputStream.close()            } catch (e: java.lang.Exception) {                e.printStackTrace()                ip = "103.139.75.200"            }        }    }}